const teacherClassStats = `-- name: TeacherClassStats :many
SELECT c.id AS class_id, c.name AS class_name, s.id AS subject_id, s.name AS subject_name,
       (SELECT count(*) FROM enrollments e WHERE e.class_id = c.id AND e.starts_on <= school_today()
         AND (e.ends_on IS NULL OR e.ends_on >= school_today()))::int AS students,
       COALESCE((SELECT sum(g.value * lw.weight) / NULLIF(sum(lw.weight), 0)
          FROM grades g JOIN lesson_works lw ON lw.id = g.lesson_work_id JOIN lessons l ON l.id = lw.lesson_id
         WHERE l.teacher_id = ta.teacher_id AND l.class_id = c.id AND l.subject_id = s.id
           AND g.academic_period_id = ta.academic_period_id AND g.deleted_at IS NULL), -1)::float8 AS average,
       COALESCE((SELECT count(*) FILTER (WHERE a.status IN ('present','late'))::float8 / NULLIF(count(*) FILTER (WHERE a.status <> 'exempt'), 0)
          FROM attendance a JOIN lessons l ON l.id = a.lesson_id
         WHERE l.teacher_id = ta.teacher_id AND l.class_id = c.id AND l.subject_id = s.id
           AND l.academic_period_id = ta.academic_period_id), -1)::float8 AS attendance_rate
FROM teaching_assignments ta
JOIN classes c ON c.id = ta.class_id AND c.archived_at IS NULL
JOIN subjects s ON s.id = ta.subject_id
WHERE ta.teacher_id = $1 AND ta.academic_period_id = $2
  AND ta.starts_on <= school_today() AND (ta.ends_on IS NULL OR ta.ends_on >= school_today())
ORDER BY c.name, s.name
`

type TeacherClassStatsParams struct {
	TeacherID        uuid.UUID `json:"teacher_id"`
	AcademicPeriodID uuid.UUID `json:"academic_period_id"`
}

type TeacherClassStatsRow struct {
	ClassID        uuid.UUID `json:"class_id"`
	ClassName      string    `json:"class_name"`
	SubjectID      uuid.UUID `json:"subject_id"`
	SubjectName    string    `json:"subject_name"`
	Students       int32     `json:"students"`
	Average        float64   `json:"average"`
	AttendanceRate float64   `json:"attendance_rate"`
}

func (q *Queries) TeacherClassStats(ctx context.Context, arg TeacherClassStatsParams) ([]TeacherClassStatsRow, error) {
	rows, err := q.db.Query(ctx, teacherClassStats, arg.TeacherID, arg.AcademicPeriodID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []TeacherClassStatsRow{}
	for rows.Next() {
		var i TeacherClassStatsRow
		if err := rows.Scan(
			&i.ClassID,
			&i.ClassName,
			&i.SubjectID,
			&i.SubjectName,
			&i.Students,
			&i.Average,
			&i.AttendanceRate,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

