const teacherLessonCounts = `-- name: TeacherLessonCounts :one
SELECT count(*) FILTER (WHERE l.lesson_date = $1::date AND l.status <> 'cancelled')::int AS today_lessons,
       count(*) FILTER (WHERE l.lesson_date < $1::date AND l.status = 'planned')::int AS unmarked_past_lessons
FROM lessons l WHERE l.teacher_id = $2 AND l.academic_period_id = $3
`

